let audio,last='';
export function initSound(){document.addEventListener('pointerdown',()=>{audio??=new AudioContext();audio.resume();},{once:true});}
export function fireSound(key){if(!audio||audio.state!=='running'||!document.querySelector('#sound-on')?.checked)return;const t=audio.currentTime,d=key==='attack3'?.38:.24,n=audio.createBuffer(1,Math.ceil(audio.sampleRate*d),audio.sampleRate),v=n.getChannelData(0);let seed=79,prev=0;for(let i=0;i<v.length;i++){seed=(seed*1664525+1013904223)>>>0;prev=.65*prev+.35*(seed/2147483648-1);v[i]=prev*Math.sin(Math.PI*i/v.length)**1.5;}const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=n;filter.type='bandpass';filter.frequency.setValueAtTime(1600,t);filter.frequency.exponentialRampToValueAtTime(250,t+d);filter.Q.value=.6;gain.gain.value=.6;src.connect(filter).connect(gain).connect(audio.destination);src.start(t);const osc=audio.createOscillator(),g=audio.createGain();osc.frequency.setValueAtTime(135,t);osc.frequency.exponentialRampToValueAtTime(48,t+.12);g.gain.setValueAtTime(.12,t);g.gain.exponentialRampToValueAtTime(.001,t+.15);osc.connect(g).connect(audio.destination);osc.start(t);osc.stop(t+.16);}
export function drawFire(ctx,meta,key,index,mode){if(!key.startsWith('attack')||!document.querySelector('#fire-on')?.checked)return;const a=meta.actions[key],f=a.frames[index],p=f.inspectionPoint,ox=meta.stage.actorX,oy=meta.stage.actorY;if(index===0||index===a.frames.length-1&&key!=='attack3')return;const attacking=['drive','contact','follow-through','hook-forward-low','hook-forward','hook-arc-up','hook-peak'].includes(f.phase);ctx.save();ctx.translate(ox,oy);ctx.lineCap='round';ctx.lineJoin='round';const points=a.frames.slice(key==='attack3'?1:1,index+1).map(x=>x.inspectionPoint);if(attacking&&points.length>1){for(const [color,width,alpha] of [['#c73513',19,.55],['#f46716',12,.8],['#ffc33c',5,.8]]){const edges=[[],[]];for(let j=0;j<points.length;j++){const q=points[j],prev=points[Math.max(0,j-1)],next=points[Math.min(points.length-1,j+1)],ang=Math.atan2(next[1]-prev[1],next[0]-prev[0])+Math.PI/2,w=width*(.1+.9*j/(points.length-1));for(let side=0;side<2;side++){const z=side?1:-1;edges[side].push([q[0]+Math.cos(ang)*w*z,q[1]+Math.sin(ang)*w*z]);}}const outline=edges[0].concat(edges[1].reverse());ctx.fillStyle=color;ctx.globalAlpha=alpha;ctx.beginPath();ctx.moveTo(...outline[0]);for(let j=1;j<outline.length;j++){const next=outline[(j+1)%outline.length];ctx.quadraticCurveTo(...outline[j],(outline[j][0]+next[0])/2,(outline[j][1]+next[1])/2);}ctx.closePath();ctx.fill();}for(let j=0;j<points.length-1;j++){const q=points[j];ctx.fillStyle=j%2?'#ff9c21':'#ec4913';ctx.beginPath();ctx.moveTo(q[0]-12,q[1]+9);ctx.quadraticCurveTo(q[0]-26,q[1]-5,q[0]-20,q[1]-33-j*4);ctx.quadraticCurveTo(q[0]+4,q[1]-14,q[0]+10,q[1]+7);ctx.fill();}}
ctx.globalAlpha=1;const x=p[0],y=p[1];for(let j=0;j<7;j++){const angle=j*Math.PI*2/7+index*.7,r=19+(j%3)*4;ctx.fillStyle=j%2?'#ff9c21':'#ed4d12';ctx.beginPath();ctx.moveTo(x+Math.cos(angle-.4)*16,y+Math.sin(angle-.4)*16);ctx.quadraticCurveTo(x+Math.cos(angle)*r*1.5,y+Math.sin(angle)*r*1.5-10,x+Math.cos(angle+.4)*16,y+Math.sin(angle+.4)*16);ctx.fill();}ctx.strokeStyle='#ffd45b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,18,index*.6,index*.6+Math.PI*1.3);ctx.stroke();ctx.restore();const sig=key+':'+index;if(mode==='playing'&&sig!==last&&(f.phase==='drive'||f.phase==='hook-forward'))fireSound(key);last=sig;}
